// src/components/Navbar.js
import React, { useEffect, useRef, useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import logo from '../assests/logo3.png';
import { toast } from 'react-toastify';

const Navbar = ({ isAuthenticated, user, onLogout }) => {
  const [showDropdown, setShowDropdown] = useState(false);
  const dropdownRef = useRef(null);
  const location = useLocation();
  const navigate = useNavigate();
  const inHomePage = location.pathname === '/';

  const toggleDropdown = () => setShowDropdown(prev => !prev);

  const handleLogout = () => {
    setShowDropdown(false);
    onLogout();
    toast.info('You have been logged out.');
  };

  // Close dropdown on outside click
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Scroll to section if link clicked from non-home page
  const scrollToSection = (id) => {
    if (!inHomePage) {
      navigate(`/#${id}`);
    } else {
      const el = document.getElementById(id);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  return (
    <nav className="navbar navbar-expand-lg navbar-light bg-light shadow-sm sticky-top">
      <div className="container">
        <Link className="navbar-brand" to="/">
          <img src={logo} alt="Logo" height="40" />
        </Link>

        <button
          className="navbar-toggler"
          type="button"
          data-bs-toggle="collapse"
          data-bs-target="#navbarContent"
          aria-controls="navbarContent"
          aria-expanded="false"
          aria-label="Toggle navigation">
          <span className="navbar-toggler-icon"></span>
        </button>

        <div className="collapse navbar-collapse" id="navbarContent">
          <ul className="navbar-nav mx-auto">
            {['home', 'about', 'features', 'contact'].map((section) => (
              <li className="nav-item" key={section}>
                <span
                  className="nav-link"
                  style={{ cursor: 'pointer' }}
                  onClick={() => scrollToSection(section)}
                >
                  {section.charAt(0).toUpperCase() + section.slice(1)}
                </span>
              </li>
            ))}
          </ul>

          <div className="d-flex align-items-center">
            {isAuthenticated ? (
              <div className="dropdown" ref={dropdownRef}>
                <span
                  className="nav-link dropdown-toggle text-warning"
                  role="button"
                  onClick={toggleDropdown}
                >
                  {user && user.name}
                </span>
                {showDropdown && (
                  <ul className="dropdown-menu dropdown-menu-end show" style={{ position: 'absolute' }}>
                    <li>
                      <button className="dropdown-item" onClick={handleLogout}>Logout</button>
                    </li>
                  </ul>
                )}
              </div>
            ) : (
              <div>
                <Link className="btn btn-outline-primary me-2" to="/signin">Sign In</Link>
                <Link className="btn btn-primary" to="/signup">Sign Up</Link>
              </div>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
